import json, os, pathlib, subprocess
def run(argv):
    p=subprocess.run(argv,text=True,capture_output=True,check=False)
    return {'argv':argv,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
services=['hadalis-chatgpt.service','hadalis-worker.service','hadalis-chat-bridge.service']
out={'job_cwd':os.getcwd(),'parent_pid':os.getppid()}
try: out['parent_cwd']=os.readlink(f'/proc/{os.getppid()}/cwd')
except OSError as e: out['parent_cwd_error']=str(e)
out['units']={}
for s in services:
    out['units'][s]={'show':run(['systemctl','--user','show',s,'--no-pager','--property=LoadState','--property=ActiveState','--property=SubState','--property=FragmentPath','--property=WorkingDirectory','--property=ExecStart']),'cat':run(['systemctl','--user','cat',s,'--no-pager'])}
pc=out.get('parent_cwd')
if pc:
    out['parent_git']={
      'toplevel':run(['git','-C',pc,'rev-parse','--show-toplevel']),
      'head':run(['git','-C',pc,'rev-parse','HEAD']),
      'branch':run(['git','-C',pc,'branch','--show-current']),
      'origin':run(['git','-C',pc,'remote','get-url','origin']),
      'status':run(['git','-C',pc,'status','--porcelain=v1'])
    }
print(json.dumps(out,indent=2,sort_keys=True))
